namespace help.screenshot;




using org.junit;

using docking.widgets.table;
using ghidra.app.plugin.core.functionwindow;

public class FunctionWindowPluginScreenShots : GhidraScreenShotGenerator {

	public FunctionWindowPluginScreenShots() : base()
    {
	}

	/* @Test */
	public void testFunctionWindow() {
		showProvider(typeof(FunctionWindowProvider));
		setColumnSizes();
		captureIsolatedProvider(typeof(FunctionWindowProvider), 700, 300);
	}

	private void setColumnSizes() {
		// note: these values are rough values found by trial-and-error
		FunctionWindowProvider provider = getProvider(typeof(FunctionWindowProvider));
		GTable table = (GTable) getInstanceField("functionTable", provider);
		runSwing(new _Anon_Runnable_1());

	}

	internal class _Anon_Runnable_1 : Runnable
	{

			/* @Override */
			public void run() {
				TableColumnModel columnModel = table.getColumnModel();
				int columnCount = columnModel.getColumnCount();
				for (int i = 0; i < columnCount; i++) {
					TableColumn column = columnModel.getColumn(i);
					object headerValue = column.getHeaderValue();
					if ("Name".equals(headerValue)) {
						column.setPreferredWidth(85);
					}
					else if ("Location".equals(headerValue)) {
						column.setPreferredWidth(70);
					}
					else if ("Function Signature".equals(headerValue)) {
						column.setPreferredWidth(400);
					}
					else if ("Function Size".equals(headerValue)) {
						column.setPreferredWidth(25);
					}
				}
			}
		
	}

}
